<?php $ph=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<section class="payroll-tools"><h2><i class="fa-solid fa-users" aria-hidden="true"></i> Staff payroll</h2><p>Open a staff record to generate a payslip or configure automatic allowances.</p>
<form method="get" class="payroll-filters"><label>Search staff<input type="search" name="q" value="<?= $ph($staffSearch) ?>" placeholder="Name, ID, role or department"></label><label>Allowance filter<select name="allowance_filter"><?php foreach(['all'=>'All staff','eligible'=>'Eligible existing staff','with_allowance'=>'With configured allowance'] as $key=>$label): ?><option value="<?= $key ?>" <?= $staffFilter===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></label><label>Sort by<select name="sort"><option value="name">Name</option><option value="tenured" <?= $staffSort==='tenured'?'selected':'' ?>>Allowance eligibility and amount</option></select></label><button type="submit">Search</button><a class="payroll-clear" href="<?= $ph(route('hr.payroll')) ?>"><i class="fa-solid fa-filter-circle-xmark" aria-hidden="true"></i> Clear</a></form>
<p><?= count($staff) ?> staff record(s)</p><div class="payroll-table-wrap"><table><thead><tr><th>Staff member</th><th>Role / department</th><th>Allowance per cutoff</th><th>Action</th></tr></thead><tbody><?php foreach($staff as $person): ?><tr><td><strong><?= $ph($person['full_name']) ?></strong><small><?= $ph($person['employee_id']??'No ID') ?></small></td><td><?= $ph($person['role']==='hr'?'Human Resource':ucfirst($person['role'])) ?><small><?= $ph($person['department_name']??'Unassigned') ?></small></td><td><?= $person['is_tenured']?$ph(money((float)$person['allowance'])):'Not enabled' ?><?php if($person['effective_from']): ?><small>Effective <?= $ph($person['effective_from']) ?></small><?php endif ?></td><td><a class="app-button secondary" data-open-payroll="<?= (int)$person['id'] ?>" href="<?= $ph(route('hr.payroll').'?'.http_build_query(['employee_id'=>$person['id'],'q'=>$staffSearch,'allowance_filter'=>$staffFilter,'sort'=>$staffSort,'cutoff_start'=>$cutoffStart])) ?>">Open payroll</a></td></tr><?php endforeach ?><?php if(!$staff): ?><tr><td colspan="4">No staff match these filters.</td></tr><?php endif ?></tbody></table></div></section>
